#!/usr/bin/env Rscript
options(stringsAsFactors=FALSE,warn=1)
suppressPackageStartupMessages({library(ggplot2);library(readxl);library(jsonlite);library(digest)})
args<-commandArgs(TRUE);m<-if(length(args))normalizePath(args[1])else normalizePath('05_organ_network/S11b_full_pair_recompute_20261008');root<-Sys.getenv('DISCO_INPUT_ROOT');base<-file.path(root,'Result3/Organ')
pair<-readRDS(file.path(m,'input/pair_definitions_and_matrices.rds'));org<-pair$organ_order;rawscore<-read.csv(file.path(m,'input/private/organ_full_scores.csv'),check.names=FALSE);priv<-readRDS(file.path(m,'input/private/sample_and_reference.rds'));stopifnot(identical(as.character(rawscore$eid),priv$eid))
od<-readRDS(file.path(base,'UKB.odis.rds'));g<-readRDS(file.path(base,'UKB.prot.imputed.rds'));org_dots<-gsub(' ','.',org,fixed=TRUE);ix<-match(as.character(rawscore$eid),as.character(g[,'eid']));stopifnot(all(org_dots%in%names(od)),!anyNA(ix),!anyDuplicated(rawscore$eid));bridge_error<-max(abs(as.matrix(rawscore[,org])-as.matrix(od[ix,org_dots])));age_bridge_error<-max(abs(as.numeric(priv$age)-as.numeric(od$age[ix])));sex_bridge_mismatches<-sum(as.character(priv$sex)!=as.character(od$sex[ix]));stopifnot(bridge_error<1e-10,age_bridge_error==0,sex_bridge_mismatches==0)
idQA<-read_json(file.path(m,'results/id_score_bridge_acceptance.json'),simplifyVector=TRUE);stopifnot(idQA$status=='PASS',idQA$N==length(priv$eid),idQA$individual_score_pairs_checked==18L*length(priv$eid));serverQA<-read_json(file.path(m,'results/current_targets_acceptance.json'),simplifyVector=TRUE);stopifnot(serverQA$status=='PASS',serverQA$N_scores==length(priv$eid));current<-read.csv(file.path(m,'results/current_target_models_162.csv'));current$organ<-gsub('.',' ',current$organ,fixed=TRUE);stopifnot(setequal(org,unique(current$organ)))
age_target<-vapply(org,function(o)cor(rawscore[[o]],priv$age),0);mort<-current[current$outcome=='All-cause mortality',];stopifnot(nrow(mort)==18);mort_target<-mort$C[match(org,mort$organ)];disease_target<-vapply(org,function(o){z<-current[current$organ==o & current$outcome!='All-cause mortality',];stopifnot(nrow(z)==8);mean(z$C)},0)
targets_new<-list('Correlation with age'=age_target,'C-index for mortality'=mort_target,'C-index for disease'=disease_target)
cs<-readRDS(file.path(base,'Tissue.cs1.rds'));getcs<-function(v){z<-cs[cs$variable==v,];z$value[match(org,as.character(z$tissue))]}
excel<-read_excel(file.path(base,'Disease_cindex.xlsx'));old_dc<-setNames(numeric(18),org)
for(k in 1:18){start<-2+(k-1)*9;name<-as.character(excel[[1]][start]);values<-as.numeric(excel[[8]][start+1:8]);stopifnot(length(values)==8,all(is.finite(values)),name%in%org);old_dc[name]<-mean(values)}
targets_old<-list('Correlation with age'=getcs('Corr'),'C-index for mortality'=getcs('C-index'),'C-index for disease'=unname(old_dc[org]))
powers<-seq(.5,4,.5);calculate<-function(mat,targets,branch){diag(mat)<-0;stopifnot(all(mat>=0));out<-list();k<-0L;for(p in powers)for(outcome in names(targets)){degree<-rowSums(mat^p);target<-targets[[outcome]];test<-cor.test(degree,target,method='pearson');a<-degree-mean(degree);b<-target-mean(target);independent<-sum(a*b)/sqrt(sum(a*a)*sum(b*b));stopifnot(abs(test$estimate-independent)<1e-12);k<-k+1L;out[[k]]<-data.frame(branch=branch,power=p,outcome=outcome,N_organ=18,r=unname(test$estimate),P=test$p.value,independent_r=independent)};do.call(rbind,out)}
branches<-rbind(calculate(pair$matrix_historical,targets_old,'historical_matrix_historical_targets'),calculate(pair$matrix_new,targets_old,'recomputed_matrix_historical_targets'),calculate(pair$matrix_historical,targets_new,'historical_matrix_current_targets'),calculate(pair$matrix_new,targets_new,'recomputed_matrix_current_targets'))
final<-branches[branches$branch=='recomputed_matrix_current_targets',];stopifnot(nrow(final)==24,!anyDuplicated(final[,c('power','outcome')]));outcomes<-names(targets_new);final$outcome<-factor(final$outcome,levels=outcomes)
colours<-c('Correlation with age'='#E64B35','C-index for mortality'='#00A087','C-index for disease'='#3C5488')
p<-ggplot(final,aes(power,r,colour=outcome,group=outcome))+geom_line(linewidth=.8)+geom_point(size=2.5)+scale_colour_manual(values=colours,breaks=outcomes,labels=c('Age correlation','Mortality C-index','Disease C-index'),name=NULL)+scale_x_continuous(breaks=powers)+labs(x='Weighted power',y='Pearson correlation coefficient')+theme_classic(base_size=12)+theme(legend.position='bottom',legend.text=element_text(size=10))
ggsave(file.path(m,'figures/S11b_FULL_PAIR_CURRENT_TARGETS_NEW_CALCULATION.pdf'),p,width=6,height=4,device='pdf')
write.csv(final,file.path(m,'tables/S11b_current_24_keyed_points.csv'),row.names=FALSE);write.csv(branches,file.path(m,'results/S11b_four_branch_96_points.csv'),row.names=FALSE);write.csv(data.frame(organ=org,age_correlation=age_target,mortality_C=mort_target,mean_eight_disease_C=disease_target),file.path(m,'tables/S11b_current_targets_18_organs.csv'),row.names=FALSE)
old<-read.csv(file.path(root,'Results_final/05_organ_network/s11b_transparent_20261007/fixed_20261007/S11b_weighted_power_data.csv'));oldbranch<-branches[branches$branch=='historical_matrix_historical_targets',];compare<-merge(oldbranch,old,by=c('power','outcome'),suffixes=c('_new','_accepted'));stopifnot(nrow(compare)==24);history_error<-max(abs(compare$r_new-compare$r_accepted));stopifnot(history_error<1e-12)
qa<-list(status='PASS',new_final_points=24,four_branch_comparison_points=96,original_network_weight_power_definition=TRUE,all24_keys_unique=TRUE,manual_Pearson_max_error=max(abs(branches$r-branches$independent_r)),accepted_historical_aggregate_reconstruction_max_error=history_error,local_recomputed_full_scores_vs_accepted_ODIS_max_error=bridge_error,server_score_source='Existing server input_organ.csv, generated from the same unchanged UKB.odis.rds by export_organ_inputs.R; no new individual score upload performed',server_input_hashes=serverQA$input_sha256,N=length(priv$eid),current_target_rows=nrow(current),current_target_model_warnings=serverQA$model_warning_count,original_gene_QC_and_raw_scoring_completed=TRUE,network_pairwise_age_sex_completed=TRUE,LASSO_selection_lists='Original saved input definitions retained; upstream organ LASSO training is NOT retrained in this weighted-power task',new_final_r_range=range(final$r),new_final_P_range=range(final$P),historical_exact_power_producer_recovered=FALSE,estimand='Across18organs, weighted degree vs age correlation/crude apparent mortality C/mean8crude apparent disease C; not individual predictive validation or causality')
write_json(qa,file.path(m,'results/numerical_acceptance.json'),pretty=TRUE,auto_unbox=TRUE,digits=17);print(qa);writeLines(capture.output(sessionInfo()),file.path(m,'logs/plot_sessionInfo.txt'))
